* Feedback network and Load (Figure 26.24 topology)
R3 vop vm 20000.0
R4 vm vip 20000.0
R5 vom vp 20000.0
R6 vp vim 20000.0
C5 vop 0 2.5e-13
C6 vom 0 2.5e-13

* Differential Input Sources
Vcom_in vcom_in 0 0.5
Vdiff_in vdiff_in 0 PULSE(-0.2 0.2 75n 0.5n 0.5n 5n 10n)
Evip vip 0 VALUE={v(vcom_in) + 0.5*v(vdiff_in)}
Evim vim 0 VALUE={v(vcom_in) - 0.5*v(vdiff_in)}

.control
* 1. Operating point analysis
op
let idd = -i(VDD)
let vocm = 0.5 * (v(vop) + v(vom))
print idd vocm v(VCMFB) v(Vbiasn) v(Vbiasp)

* 2. Transient step response (Baker Fig. 26.35: 70ns to 90ns)
tran 0.05n 90n 70n
let vout_diff = v(vop) - v(vom)
let vin_diff = v(vip) - v(vim)
meas tran vout_max max v(vop)
meas tran vout_min min v(vop)
meas tran swing_diff param='vout_max - vout_min'
meas tran t_rise trig vout_diff val=0.1 rise=1 targ vout_diff val=0.35 rise=1
print swing_diff

* 3. DC Sweep for Open-Loop Gain and Balance
dc Vdiff_in -0.05 0.05 0.0005
let vodiff = v(vop) - v(vom)
let gain_diff = deriv(vodiff)
meas dc max_gain max gain_diff
print max_gain

quit
.endc
.end

